import math

def is_square(k):
    if k < 0:
        return False
    sqrt_k = int(math.isqrt(k))
    return sqrt_k * sqrt_k == k

def solve_cool_integer(n):
    """
    Checks if an integer n is a cool integer using backtracking search.
    """
    # available numbers are 1 to n. We use a boolean array for tracking usage.
    used = [False] * (n + 1)

    def backtrack(current_sum, count):
        if count == n:
            # Successfully built a permutation of length n
            return True

        for x in range(1, n + 1):
            if not used[x]:
                next_sum = current_sum + x

                # Constraint check: the prefix sum must NOT be a perfect square
                if not is_square(next_sum):
                    # Try using x
                    used[x] = True
                    if backtrack(next_sum, count + 1):
                        return True
                    # Backtrack: unuse x
                    used[x] = False

        return False

    # Start the search. Initial sum is 0, count is 0.
    return backtrack(0, 0)

# Test for n from 1 to 40
results = {}
for n in range(1, 41):
    is_cool = solve_cool_integer(n)
    results[n] = is_cool

cool_integers = [n for n, is_cool in results.items() if is_cool]

print("--- Results for n=1 to 40 ---")
for n in range(1, 41):
    print(f"n={n}: Cool = {results[n]}")

print("\n--- Cool Integers Found ---")
print(f"The cool integers are: {cool_integers}")

