    return sqrt_k * sqrt_k == k

def check_triangular_square(n):
    # S_n = n * (n + 1) / 2
    total_sum = n * (n + 1) // 2
    return is_square(total_sum)

# Check n from 1 up to 100
non_cool_candidates = []
for n in range(1, 101):
    if check_triangular_square(n):
        non_cool_candidates.append(n)

print("Triangular numbers that are squares (Non-cool candidates):")
print(non_cool_candidates)
